-- Textos del sitio: el método no es solo H1 y M5 (es la base, pero no lo único).
-- Cambia esas frases en los textos guardados de la página. Se puede correr varias veces.
update public.site_settings set data = replace(data::text, 'en momentos reales del mercado, en H1 y M5.', 'en momentos reales del mercado, en la temporalidad que pida cada ejercicio.')::jsonb where id = 1 and data::text like '%en momentos reales del mercado, en H1 y M5.%';
update public.site_settings set data = replace(data::text, 'Zona en la temporalidad mayor y stop loss en M5, como en tu plataforma.', 'Marca tu zona y tu stop loss como lo harías en tu plataforma.')::jsonb where id = 1 and data::text like '%Zona en la temporalidad mayor y stop loss en M5, como en tu plataforma.%';
update public.site_settings set data = replace(data::text, '10 índices con práctica en gráficas reales H1 y M5.', '10 índices con práctica en gráficas reales.')::jsonb where id = 1 and data::text like '%10 índices con práctica en gráficas reales H1 y M5.%';
update public.site_settings set data = replace(data::text, 'Marca la zona, baja a M5 para el stop loss y mira la repetición vela por vela.', 'Marca la zona, pon tu stop loss y mira la repetición vela por vela.')::jsonb where id = 1 and data::text like '%Marca la zona, baja a M5 para el stop loss y mira la repetición vela por vela.%';
update public.site_settings set data = replace(data::text, 'Zona en H1 y stop loss en M5: lo mismo que ves en mis videos', 'Estructura, zonas, entradas y gestión: lo mismo que ves en mis videos')::jsonb where id = 1 and data::text like '%Zona en H1 y stop loss en M5: lo mismo que ves en mis videos%';
update public.site_settings set data = replace(data::text, 'cómo encuentro mis zonas en H1, dónde pongo el stop loss en M5 y cómo gestiono el riesgo.', 'cómo leo la estructura, cómo encuentro mis zonas, cómo y cuándo entro, dónde pongo el stop loss y cómo gestiono el riesgo.')::jsonb where id = 1 and data::text like '%cómo encuentro mis zonas en H1, dónde pongo el stop loss en M5 y cómo gestiono el riesgo.%';
update public.slides set body = replace(body, 'baja a M5 para el stop loss', 'pon tu stop loss') where body like '%baja a M5 para el stop loss%';
